<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Expense Tracker</title>
<style>
body { font-family: Arial, sans-serif; max-width: 800px; margin: 20px auto; padding: 10px; }
form { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 20px; }
input, select, button { padding: 8px; font-size: 14px; }
button { cursor: pointer; }
#expenses table { width: 100%; border-collapse: collapse; margin-top: 20px; }
th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
tr.expense { /* expense rows */ }
.exp-del { background: none; border: none; color: red; cursor: pointer; font-size: 14px; }
.cat-total { display: inline-block; margin-right: 20px; }
#total { font-weight: bold; font-size: 18px; margin-top: 10px; }
#form-error { color: red; min-height: 20px; }
</style>
</head>
<body>

<h1>Personal Expense Tracker</h1>

<form id="expense-form">
  <input type="number" id="amount" step="0.01" placeholder="Amount" required>
  <select id="category">
    <option value="">Category</option>
    <option value="groceries">Groceries</option>
    <option value="transport">Transport</option>
    <option value="bills">Bills</option>
    <option value="fun">Fun</option>
  </select>
  <input type="date" id="date" required>
  <input type="text" id="note" placeholder="Note (optional)">
  <button type="submit" id="add-expense">Add Expense</button>
</form>
<div id="form-error"></div>

<h3>Filter Expenses</h3>
<select id="filter-category">
  <option value="all">All Categories</option>
  <option value="groceries">Groceries</option>
  <option value="transport">Transport</option>
  <option value="bills">Bills</option>
  <option value="fun">Fun</option>
</select>
<input type="date" id="filter-from">
<input type="date" id="filter-to">

<h3>Total: <span id="total">0.00</span></h3>
<div id="category-summary"></div>

<div id="expenses"></div>

<script>
let expenses = [];
const categories = ['groceries', 'transport', 'bills', 'fun'];

// Load from localStorage
const saved = localStorage.getItem('expenses');
if (saved) {
  try {
    expenses = JSON.parse(saved);
  } catch(e) {}
}

// Render expenses list
function renderExpenses() {
  const container = document.getElementById('expenses');
  const filterCat = document.getElementById('filter-category').value;
  const filterFrom = document.getElementById('filter-from').value;
  const filterTo = document.getElementById('filter-to').value;

  let visibleCount = 0;
  let filteredExpenses = expenses.filter(exp => {
    // Category filter
    if (filterCat !== 'all' && exp.category !== filterCat) return false;
    // Date filters
    const expDate = new Date(exp.date);
    if (filterFrom && expDate < new Date(filterFrom)) return false;
    if (filterTo && expDate > new Date(filterTo)) return false;
    return true;
  });

  // Reverse for newest first
  filteredExpenses.reverse();

  visibleCount = filteredExpenses.length;
  container.innerHTML = '';

  if (visibleCount === 0) {
    container.innerHTML = '<p>No expenses to display.</p>';
  } else {
    const table = document.createElement('table');
    table.setAttribute('cellspacing', '0');
    table.setAttribute('cellpadding', '5');
    const headRow = table.insertRow();
    ['Amount', 'Category', 'Date', 'Note', 'Action'].forEach(text => {
      const th = document.createElement('th');
      th.textContent = text;
      headRow.appendChild(th);
    });

    filteredExpenses.forEach((exp, index) => {
      const row = table.insertRow();
      row.className = 'expense';
      row.dataset.originalIndex = expenses.indexOf(exp);

      const tdAmount = row.insertCell(0);
      tdAmount.textContent = parseFloat(exp.amount).toFixed(2);

      const tdCat = row.insertCell(1);
      tdCat.textContent = exp.category;

      const tdDate = row.insertCell(2);
      tdDate.textContent = exp.date;

      const tdNote = row.insertCell(3);
      tdNote.textContent = exp.note || '';

      const tdAction = row.insertCell(4);
      const delBtn = document.createElement('button');
      delBtn.className = 'exp-del';
      delBtn.innerHTML = '&times;';
      delBtn.title = 'Delete';
      delBtn.onclick = function(e) {
        e.stopPropagation();
        const originalIndex = parseInt(row.dataset.originalIndex);
        expenses.splice(originalIndex, 1);
        localStorage.setItem('expenses', JSON.stringify(expenses));
        renderExpenses();
      };
      tdAction.appendChild(delBtn);
    });

    container.appendChild(table);
  }

  // Update total for visible items
  const total = filteredExpenses.reduce((sum, exp) => sum + parseFloat(exp.amount), 0);
  document.getElementById('total').textContent = total.toFixed(2);

  // Category summary
  updateCategorySummary(filteredExpenses);
}

// Update category totals display
function updateCategorySummary(filteredExpenses) {
  const summaryDiv = document.getElementById('category-summary');
  const catTotals = {};

  categories.forEach(cat => {
    catTotals[cat] = filteredExpenses
      .filter(exp => exp.category === cat)
      .reduce((sum, exp) => sum + parseFloat(exp.amount), 0);
  });

  summaryDiv.innerHTML = '';
  categories.forEach(cat => {
    const span = document.createElement('span');
    span.className = 'cat-total';
    span.dataset.cat = cat;
    span.textContent = `${cat}: ${catTotals[cat].toFixed(2)}`;
    summaryDiv.appendChild(span);
  });
}

// Form submission handling
document.getElementById('expense-form').addEventListener('submit', function(e) {
  e.preventDefault();

  const amountInput = document.getElementById('amount');
  const categorySelect = document.getElementById('category');
  const dateInput = document.getElementById('date');
  const noteInput = document.getElementById('note');
  const errorDiv = document.getElementById('form-error');

  // Validation: check for empty/zero/negative/non-numeric amount or missing date
  const amountValue = amountInput.value.trim();
  if (!amountValue || isNaN(parseFloat(amountValue)) || parseFloat(amountValue) <= 0) {
    errorDiv.textContent = 'Please enter a valid positive amount.';
    return;
  }

  const categoryValue = categorySelect.value;
  const dateValue = dateInput.value;

  if (!dateValue) {
    errorDiv.textContent = 'Date is required.';
    return;
  }

  // Valid submission - add expense
  const newExpense = {
    amount: parseFloat(amountValue),
    category: categoryValue,
    date: dateValue,
    note: noteInput.value.trim()
  };

  expenses.push(newExpense);
  localStorage.setItem('expenses', JSON.stringify(expenses));

  // Clear error and reset form
  errorDiv.textContent = '';
  amountInput.value = '';
  categorySelect.value = '';
  dateInput.value = '';
  noteInput.value = '';

  renderExpenses();
});

// Filter event listeners
document.getElementById('filter-category').addEventListener('change', function() {
  renderExpenses();
});

document.getElementById('filter-from').addEventListener('change', function() {
  renderExpenses();
});

document.getElementById('filter-to').addEventListener('change', function() {
  renderExpenses();
});

// Initial render
renderExpenses();
</script>

</body>
</html>
